//! x86-64 syscall names, generated by build.rs from `<asm/unistd_64.h>`.

include!(concat!(env!("OUT_DIR"), "/syscalls.rs"));

/// Name of syscall `nr`, falling back to `syscall_<nr>`.
pub fn name(nr: u64) -> String {
    SYSCALL_NAMES
        .binary_search_by_key(&nr, |&(n, _)| n)
        .map(|i| SYSCALL_NAMES[i].1.to_string())
        .unwrap_or_else(|_| format!("syscall_{nr}"))
}
